sites.find:
shift_rank = SUB_HIGH_SCORE_TOP_TEN_COUNT;
if (rank >= shift_rank)
    return;

SubSolution* shift_cursor = &bank->survival_records[shift_rank];
do {
    --shift_cursor;
    shift_cursor[1] = shift_cursor[0];
    shift_cursor[1].route_or_rank_index = shift_rank;
    --shift_rank;
} while (shift_rank > rank);

